insert into public.digest_runs (id, date, status, total_articles, included_articles, duration, errors, triggered_by, preview, selected_article_ids)
select
  item->>'id',
  (item->>'date')::timestamptz,
  item->>'status',
  (item->>'totalArticles')::integer,
  (item->>'includedArticles')::integer,
  item->>'duration',
  coalesce(item->'errors', '[]'::jsonb),
  item->>'triggeredBy',
  case
    when item->>'id' = coalesce(data->'lastDigest'->'run'->>'id', '') then coalesce(data->'lastDigest'->>'preview', '')
    else ''
  end,
  case
    when item->>'id' = coalesce(data->'lastDigest'->'run'->>'id', '') then array(select jsonb_array_elements_text(coalesce(data->'lastDigest'->'selectedArticleIds', '[]'::jsonb)))
    else '{}'::text[]
  end
from snapshot, jsonb_array_elements(data->'runs') as item;

